import SwiftUI

struct AchievementsView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - View State

    @State private var isLoading = true

    private let categories = [
        "food_logging",
        "step_goal",
        "weight_checkin",
        "weekly_challenge"
    ]

    var body: some View {

        ScrollView {

            VStack(alignment: .leading, spacing: 20) {

                // MARK: - Achievement Summary

                HStack {

                    VStack(alignment: .leading, spacing: 4) {

                        Text("Your Achievements")
                            .font(.title2)
                            .fontWeight(.bold)

                        Text(
                            "\(gamificationViewModel.achievements.filter { $0.unlocked }.count) / \(gamificationViewModel.achievements.count) Unlocked"
                        )
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                    }

                    Spacer()

                    Image(systemName: "medal.fill")
                        .font(.largeTitle)
                        .foregroundColor(.yellow)
                }

                // MARK: - Achievement List

                if isLoading {

                    ProgressView("Loading achievements...")
                        .frame(maxWidth: .infinity)
                        .padding()

                } else if gamificationViewModel.achievements.isEmpty {

                    Text("No achievements available.")
                        .foregroundColor(.secondary)

                } else {

                    ForEach(categories, id: \.self) { category in

                        VStack(alignment: .leading, spacing: 12) {

                            Text(categoryTitle(for: category))
                                .font(.title3)
                                .fontWeight(.bold)

                            ForEach(
                                gamificationViewModel.achievements.filter {
                                    $0.activity_type == category
                                }
                            ) { achievement in

                                achievementCard(achievement)
                            }
                        }
                    }
                }
            
            }
            .padding()
        }

        // MARK: - Apply Equipped App Theme

        .modifier(
            ProjectHealthThemeModifier(
                gamificationViewModel: gamificationViewModel
            )
        )

        .navigationTitle("Achievements")
        .navigationBarTitleDisplayMode(.inline)


        // MARK: - Load Achievements

        .task {

            isLoading = true

            await gamificationViewModel.refreshAchievementProgress()

            // Unlock any achievements already earned
            await gamificationViewModel.claimEarnedAchievements()

            isLoading = false
        }

        // MARK: - Pull to Refresh

        .refreshable {

            await gamificationViewModel.refreshAchievementProgress()

            await gamificationViewModel.claimEarnedAchievements()
        }

    } // Closes body

    // MARK: - Achievement Card

    private func achievementCard(
        _ achievement: AchievementProgressResponse
    ) -> some View {

        VStack(alignment: .leading, spacing: 12) {

            HStack(spacing: 12) {

                Image(systemName: achievement.icon_name)
                    .font(.title2)
                    .foregroundColor(
                        tierColor(for: achievement.tier)
                    )
                    .frame(width: 40)

                VStack(alignment: .leading, spacing: 4) {

                    Text(achievement.title)
                        .font(.headline)

                    Text(achievement.tier.capitalized)
                        .font(.caption)
                        .fontWeight(.semibold)
                        .foregroundColor(
                            tierColor(for: achievement.tier)
                        )
                }

                Spacer()

                if achievement.unlocked {

                    Image(systemName: "checkmark.seal.fill")
                        .foregroundColor(.green)
                        .font(.title2)

                } else {

                    Image(systemName: "lock.fill")
                        .foregroundColor(.secondary)
                }
            }

            // MARK: - Description

            Text(achievement.description)
                .font(.subheadline)
                .foregroundColor(.secondary)

            // MARK: - Progress

            HStack {

                Text("Progress")
                    .font(.caption)

                Spacer()

                Text(
                    "\(achievement.current_count) / \(achievement.target_count)"
                )
                .font(.caption)
                .fontWeight(.semibold)
            }

            ProgressView(
                value: Double(
                    min(
                        achievement.current_count,
                        achievement.target_count
                    )
                ),
                total: Double(
                    max(achievement.target_count, 1)
                )
            )
            .tint(tierColor(for: achievement.tier))

            Divider()

            // MARK: - Rewards

            HStack {

                Label(
                    "+\(achievement.reward_xp) XP",
                    systemImage: "star.fill"
                )

                Spacer()

                Label(
                    "+\(achievement.reward_fragments)",
                    systemImage: "hammer.fill"
                )
            }
            .font(.caption)

            // MARK: - Unlock Status

            if achievement.unlocked {

                Label(
                    "Achievement Unlocked!",
                    systemImage: "checkmark.circle.fill"
                )
                .foregroundColor(.green)
                .font(.caption)

            } else if achievement.current_count >= achievement.target_count {

                Text("Ready to unlock")
                    .font(.caption)
                    .foregroundColor(.orange)
            }
        }
        .padding()
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color(.secondarySystemGroupedBackground))
        .cornerRadius(16)
    }

    // MARK: - Category Title

    private func categoryTitle(for category: String) -> String {

        switch category {

        case "food_logging":
            return "Food Logging"

        case "step_goal":
            return "Step Goals"

        case "weight_checkin":
            return "Weight Check-ins"

        case "weekly_challenge":
            return "Weekly Challenges"

        default:
            return "Other Achievements"
        }
    }

    // MARK: - Achievement Tier Color

    private func tierColor(for tier: String) -> Color {

        switch tier {

        case "bronze":
            return .brown

        case "silver":
            return .gray

        case "gold":
            return .yellow

        default:
            return .secondary
        }
    }

} // Closes AchievementsView
